code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    uniform = [(r, row[0]) for r, row in enumerate(grid) if all(v == row[0] for v in row)]
    background = None
    for r, value in uniform:
        if 0 < r < h - 1 and any(v != value for v in grid[r - 1]) and any(v != value for v in grid[r + 1]):
            background = value
            break
    if background is None:
        background = counts.most_common(1)[0][0]
    colors = [c for c in counts if c != background]
    if not colors:
        return out
    color = max(colors, key=lambda c: counts[c])
    # Work on the first band of non-background rows.
    start = next((r for r, row in enumerate(grid) if any(v != background for v in row)), None)
    if start is None:
        return out
    end = start
    while end + 1 < h and any(v != background for v in grid[end + 1]):
        end += 1
    band = range(start, end + 1)
    rightmost = max((c for r in band for c, v in enumerate(grid[r]) if v == color), default=-1)
    if rightmost < 0:
        return out
    for r in band:
        cols = [c for c, v in enumerate(grid[r]) if v == color]
        if cols and max(cols) == rightmost:
            for c in range(rightmost + 1, w):
                if grid[r][c] == background:
                    out[r][c] = 1
    if rightmost == w - 1:
        for r in band:
            cols = [c for c, v in enumerate(grid[r]) if v == color]
            if cols == [w - 1]:
                for c in range(w - 1):
                    if grid[r][c] == background:
                        out[r][c] = 1
    return out
'''
